import csv

def fx_rate(date: str) -> float:
    """Return the USD->EUR closing rate on the given date, read from data/ecb_rates_2019.csv."""
    file_path = __import__('os').path.join('data', 'ecb_rates_2019.csv')
    with open(file_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row.get('Date') == date:
                # Assuming column name for rate is either 'USD/EUR' or similar
                for key, val in row.items():
                    if key.lower().replace(' ', '') == 'usdeur' or key.lower() == 'rate':
                        return float(val)
                # fallback: use first numeric value
                for val in row.values():
                    try:
                        return float(val)
                    except ValueError:
                        continue
    raise ValueError(f"Rate for date {date} not found")

