    def _key(v: str):
        # Split on dots, convert each part to int; missing parts treated as 0
        parts = v.split('.')
        ints = [int(p) if p.isdigit() else 0 for p in parts]
        # Pad to 3 components
        while len(ints) < 3:
            ints.append(0)
        return tuple(ints[:3])
    return sorted(vs, key=_key)

